package vn.svframe.svframemmo.cobblemon.gameplay;
import com.cobblemon.mod.common.Cobblemon;import com.cobblemon.mod.common.api.pokemon.PokemonProperties;import com.cobblemon.mod.common.pokemon.Pokemon;import net.minecraft.server.network.ServerPlayerEntity;import java.util.*;
/** Fixtures are restricted to explicit QA environments and disposable copied player data. */
public final class CosmicPokemonQa {
 private static void check(){if(!"1".equals(System.getenv("SVFRAME_RUNTIME_QA")))throw new IllegalStateException("Runtime QA disabled");}
 public static String fixture(ServerPlayerEntity p)throws Exception{check();var storage=Cobblemon.INSTANCE.getStorage();var party=storage.getParty(p);var pc=storage.getPC(p);var dex=Cobblemon.INSTANCE.getPlayerDataManager().getPokedexData(p);int i=0;for(String name:List.of("bulbasaur","charmander","squirtle","eevee","pichu","rattata")){var pokemon=PokemonProperties.Companion.parse(name+" level=10").create();if(i++<3)party.add(pokemon);else pc.add(pokemon);dex.getClass().getMethod("catch",Pokemon.class).invoke(dex,pokemon);}Cobblemon.INSTANCE.getPlayerDataManager().saveSingle(dex,com.cobblemon.mod.common.api.storage.player.PlayerInstancedDataStoreTypes.INSTANCE.getPOKEDEX());return storage(p);}
 public static String storage(ServerPlayerEntity p){check();var storage=Cobblemon.INSTANCE.getStorage();var out=new LinkedHashMap<String,Object>();var party=new ArrayList<String>();var pc=new ArrayList<String>();for(var mon:storage.getParty(p))party.add(mon.getUuid()+":"+mon.getCurrentHealth()+":"+mon.getOwnerUUID());for(var mon:storage.getPC(p))pc.add(mon.getUuid()+":"+mon.getCurrentHealth()+":"+mon.getOwnerUUID());out.put("party",party);out.put("pc",pc);out.put("dexCount",Cobblemon.INSTANCE.getPlayerDataManager().getPokedexData(p).getSpeciesRecords().size());return new com.google.gson.Gson().toJson(out);}
}
